 184→  /** Get notification content using the NotificationClient API (like Element X)
 185→   * This fetches and decrypts the event properly for background notifications */
 186→  public static getNotificationContent = async (
 187→    roomId: string,
 188→    eventId: string,
 189→  ): Promise<NotificationItem | null> => {
 190→    try {
 191→      if (!this.notificationClient) {
 192→        console.warn("Notification client not initialized");
 193→        return null;
 194→      }
 195→
 196→      const status = await this.notificationClient.getNotification(
 197→        roomId,
