1854→    if (!room) throw new Error("Room not found");
1855→
1856→    const timeline = await room.timeline();
1857→    if (!timeline) throw new Error("Timeline not found");
1858→
1859→    await timeline.pinEvent(eventId);
1860→  };
1861→
1862→  /** Unpin a message in a room */
1863→  public static unpinMessage = async (
1864→    roomId: string,
1865→    eventId: string,
1866→  ): Promise<void> => {
1867→    if (!this.instance) throw new Error("Client not initialized");
1868→
1869→    const room = this.instance.getRoom(roomId);
1870→    if (!room) throw new Error("Room not found");
1871→
1872→    const timeline = await room.timeline();
1873→    if (!timeline) throw new Error("Timeline not found");
1874→
1875→    await timeline.unpinEvent(eventId);
1876→  };
1877→
1878→  /** Check if a message is pinned */
1879→  public static isMessagePinned = async (
1880→    roomId: string,
1881→    eventId: string,
1882→  ): Promise<boolean> => {
1883→    const pinnedEvents = await this.getPinnedEventIds(roomId);
1884→    return pinnedEvents.includes(eventId);
1885→  };
